/// <summary>
/// PricingAttribute of table <c>InventTable</c> field Product.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(InventTable, Product))]
internal class GUPPricingAttributeInventTableProduct extends GUPPricingAttributeInventTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, Product);
}

public str getRefValue(Str _defaultValue)
{
    EcoResProduct ecoResProduct;
    str ret = "";
    boolean isFirstAttributeToAppend = true;
    Query query = new Query();
    query.addDataSource(tableNum(EcoResProduct)).addRange(fieldNum(EcoResProduct, RecId)).value(_defaultValue);
    QueryRun qr = new QueryRun(query);
    while (qr.next())
    {
        ecoResProduct = qr.get(tableNum(EcoResProduct), 1);
        if (!isFirstAttributeToAppend)
        {
            ret += ",";
        }
        else
        {
            isFirstAttributeToAppend = false;
        }
        ret += ecoResProduct.DisplayProductNumber;
    }
    
    return ret;
}

public boolean validate(Str _defaultValue)
{
    var recId = str2Int64(_defaultValue);
    return EcoResProduct::find(recId) ? true : false;
}

    public void lookupAllowedValues(object _formStringControl)
    {
        EcoResProductLookup ecoResProductLookup = EcoResProductLookup::newExcludeDistinctProductVariants();
        ecoResProductLookup.parmreturnRefRecID(true);
        ecoResProductLookup.performLookupString(_formStringControl);

        return;
    }
